#pragma once
// Manager measurement log V2. No ECU I/O, no DLL modification.
// Header and data rows are generated by the same ordered field list.
// ASCII schema tokens are not UI text; units belong to the field names.
#include "mems16na_session_evidence.h"
#include <iomanip>
#include <locale>
#include <sstream>
namespace Mems16Na {
namespace LogV2 {
struct Field { std::string name, value; };
inline const char* marker(){return "# MEMS16NA_SCHEMA=2";}
inline std::string number(double v) {
    std::ostringstream s; s.imbue(std::locale::classic());
    s<<std::setprecision(15)<<v;return s.str();
}
inline std::string hex(const std::uint8_t *p,std::size_t n) {
    if(!p)return {};
    static const char chars[]="0123456789ABCDEF";
    std::string out;out.reserve(n*2);
    for(std::size_t i=0;i<n;++i){out+=chars[p[i]>>4];out+=chars[p[i]&15];}
    return out;
}
inline const char* availability(Availability a) {
    switch(a) {
    case Availability::Available:return "available";
    case Availability::NotUsed:return "not_used";
    case Availability::Unverified:return "unverified";
    default:return "missing";
    }
}
inline void value(std::vector<Field>& out,const std::string& stem,const std::string& unitKey,const Value& v) {
    out.push_back({"na_"+stem+"_raw",v.availability==Availability::Missing?"":number(v.raw)});
    out.push_back({"na_"+unitKey+"_value",v.availability==Availability::Available?number(v.calculated):""});
    out.push_back({"na_"+stem+"_availability",availability(v.availability)});
}
inline std::vector<Field> fields(const SessionEvidence& s,const std::string& timestamp) {
    const auto a=s.frame80(),b=s.frame7d();
    const bool ready=s.ready();
    const auto m=s.measurements();
    std::vector<Field> out{
        {"na_timestamp",timestamp},
        {"na_sample_valid",ready?"1":"0"},
        {"na_frame80_hex",hex(a.bytes,a.size)},
        {"na_frame7d_hex",hex(b.bytes,b.size)}
    };
    // Unchanged channels retain the previous log units and identifiers.
    out.push_back({"80x01-02_engine-rpm",ready?number(word(a,1)):""});
    out.push_back({"80x03_coolant_temp",ready?number(int(a.bytes[3])-55):""});
    out.push_back({"80x05_intake_air_temp",ready?number(int(a.bytes[5])-55):""});
    out.push_back({"80x07_map_kpa",ready?number(a.bytes[7]):""});
    out.push_back({"80x08_battery_voltage",ready?number(a.bytes[8]/10.0):""});
    out.push_back({"80x0A_idle_switch",ready?number(a.bytes[10]):""});
    out.push_back({"80x12_iac_position",ready?number(a.bytes[18]):""});
    out.push_back({"80x13-14_idle_error",ready?number(word(a,19)):""});
    out.push_back({"80x15_ignition_advance_offset",ready?number(a.bytes[21]):""});
    out.push_back({"80x16_ignition_advance",ready?number(a.bytes[22]*0.5-24.0):""});
    out.push_back({"80x17-18_coil_time",ready?number(word(a,23)*0.002):""});
    out.push_back({"80x19_crankshaft_position_sensor",ready?number(a.bytes[25]):""});
    out.push_back({"80x1A_uk4",ready?number(a.bytes[26]):""});
    out.push_back({"7dx01_ignition_switch",ready?number(b.bytes[1]):""});
    out.push_back({"7dx03_uk6",ready?number(b.bytes[3]):""});
    out.push_back({"7dx04_air_fuel_ratio",ready?number(b.bytes[4]):""});
    out.push_back({"7dx07_lambda_sensor_frequency",ready?number(b.bytes[7]):""});
    out.push_back({"7dx08_lambda_sensor_dutycycle",ready?number(b.bytes[8]):""});
    out.push_back({"7dx0C_short_term_fuel_trim",ready?number(b.bytes[12]):""});
    out.push_back({"7dx0D_carbon_canister_dutycycle",ready?number(b.bytes[13]):""});
    out.push_back({"7dx12_ignition_advance2",ready?number(b.bytes[18]):""});
    value(out,"ambient","ambient_c",m.ambient);
    value(out,"fuel","fuel_c",m.fuel);
    value(out,"pn","pn_active",m.pn);
    value(out,"ac","ac_request",m.ac);
    value(out,"idle_amplitude","idle_amplitude_rpm",m.idleAmplitude);
    value(out,"idle_signed","idle_signed_rpm",qualifiedIdleSigned(m));
    value(out,"idle_hot","idle_hot_steps",m.idleHot);
    value(out,"learn_voltage","learn_voltage_v",m.learnVoltage);
    value(out,"throttle_voltage","throttle_voltage_v",m.throttleVoltage);
    value(out,"ignition_off","ignition_off",m.ignitionOff);
    value(out,"injection_time","injection_time_us",m.injectionTime);
    value(out,"idle_base","idle_base_steps",m.idleBase);
    value(out,"idle_error","idle_error_rpm",m.idleError);
    value(out,"tps_ref1","tps_ref1_tps",m.throttleReference[0]);
    value(out,"tps_ref2","tps_ref2_tps",m.throttleReference[1]);
    value(out,"tps_ref3","tps_ref3_tps",m.throttleReference[2]);
    value(out,"tps_ref4","tps_ref4_tps",m.throttleReference[3]);
    value(out,"learn_count","learn_count",m.learnCount);
    value(out,"throttle_angle","throttle_angle_deg",m.throttleAngle);
    value(out,"lambda","lambda_mv",m.lambdaMv);
    value(out,"lambda_fault","lambda_fault",m.lambdaFault);
    value(out,"closed_loop","closed_loop",m.closedLoop);
    const Group groups[]={Group::Dtc0,Group::Dtc1,Group::Dtc2,Group::Dtc3,Group::Dtc4,Group::Dtc5,Group::Indirect7D10};
    for(int i=0;i<7;++i) {
        const auto d=s.dtc(groups[i]);
        const std::string prefix=i<6?"na_dtc"+number(i):"na_7d10";
        const bool received=d.availability!=Availability::Missing;
        out.push_back({prefix+"_raw",received?number(d.raw):""});
        out.push_back({prefix+"_availability",availability(d.availability)});
        // Unused or invalid groups cannot assert a zero fault count.
        out.push_back({prefix+"_fault_bits",d.availability==Availability::Available?number(d.faultBits):""});
        out.push_back({prefix+"_state_bits",d.availability==Availability::Available?number(d.stateBits):""});
        out.push_back({prefix+"_unknown_bits",received&&d.availability!=Availability::NotUsed?number(d.unknownBits):""});
    }
    return out;
}
inline std::string csv(const std::vector<Field>& f,bool header) {
    std::string line;
    for(const auto& field:f) {line+=",";line+=header?field.name:field.value;}
    return line;
}
inline std::string header() {return "#time"+csv(fields(SessionEvidence{},""),true);}
}
}
